sre-web-exam-day-1:
function calculateSliAvailability(successfulRequests: number, totalRequests: number): number {
  if (totalRequests <= 0) return 100;
  return Math.round((successfulRequests / totalRequests) * 100 * 10000) / 10000;
}

sre-web-assign-day-1:
function evaluateSloCompliance(sliPercent: number, sloTargetPercent: number): { compliant: boolean; delta: number } {
  const delta = Math.round((sliPercent - sloTargetPercent) * 10000) / 10000;
  return { compliant: sliPercent >= sloTargetPercent, delta };
}

sre-web-exam-day-2:
function calculateErrorBudget(totalRequests: number, sloTarget: number): { allowedErrors: number; errorBudgetPercent: number } {
  const allowedErrors = Math.floor(totalRequests * (1 - sloTarget) + 1e-9);
  const errorBudgetPercent = Math.round((1 - sloTarget) * 100 * 10000) / 10000;
  return { allowedErrors, errorBudgetPercent };
}

sre-web-assign-day-2:
function calculateBurnRate(currentErrorRate: number, allowedErrorRate: number): { burnRate: number; status: 'nominal' | 'elevated' | 'critical' } {
  const burnRate = Math.round((currentErrorRate / allowedErrorRate) * 100) / 100;
  const status = burnRate >= 10 ? 'critical' : burnRate >= 2 ? 'elevated' : 'nominal';
  return { burnRate, status };
}

sre-web-exam-day-3:
function calculateSerialAvailability(availabilities: number[]): number {
  if (availabilities.length === 0) return 1;
  const prod = availabilities.reduce((acc, a) => acc * a, 1);
  return Math.round(prod * 1000000) / 1000000;
}

sre-web-assign-day-3:
function calculateParallelAvailability(availabilities: number[]): number {
  if (availabilities.length === 0) return 0;
  const unavail = availabilities.reduce((acc, a) => acc * (1 - a), 1);
  return Math.round((1 - unavail) * 1000000) / 1000000;
}

sre-web-exam-day-4:
function calculateAllowedDowntime(sloPercent: number, periodDays: number = 30): { minutes: number; seconds: number } {
  const totalSeconds = periodDays * 24 * 3600;
  const unavailFraction = (100 - sloPercent) / 100;
  const seconds = Math.round(totalSeconds * unavailFraction);
  const minutes = Math.round((seconds / 60) * 100) / 100;
  return { minutes, seconds };
}

sre-web-assign-day-4:
function ninesToAvailability(nines: number): number {
  const val = 100 - 100 * Math.pow(0.1, nines);
  return Math.round(val * 1000000) / 1000000;
}

sre-web-exam-day-5:
function evaluateServiceReliability(sloTargetPercent: number, requests: { success: boolean; latencyMs: number }[], latencyThresholdMs: number): { availabilitySli: number; latencySli: number; compliant: boolean; budgetRemainingPercent: number } {
  if (requests.length === 0) return { availabilitySli: 100, latencySli: 100, compliant: true, budgetRemainingPercent: 100 };
  const successCount = requests.filter(r => r.success).length;
  const fastCount = requests.filter(r => r.latencyMs <= latencyThresholdMs).length;
  const availabilitySli = Math.round((successCount / requests.length) * 100 * 100) / 100;
  const latencySli = Math.round((fastCount / requests.length) * 100 * 100) / 100;
  const compliant = availabilitySli >= sloTargetPercent && latencySli >= sloTargetPercent;
  const allowedUnavail = 100 - sloTargetPercent;
  const actualUnavail = 100 - availabilitySli;
  const budgetRemainingPercent = allowedUnavail <= 0 ? 100 : Math.round(Math.max(0, 100 - (actualUnavail / allowedUnavail) * 100) * 100) / 100;
  return { availabilitySli, latencySli, compliant, budgetRemainingPercent };
}

sre-web-assign-day-5:
function computeBudgetPolicyAction(burnRate: number, budgetRemainingPercent: number): { action: 'freeze_deployments' | 'throttle_releases' | 'normal_operations'; reason: string } {
  if (budgetRemainingPercent <= 0 || burnRate >= 14.4) {
    return { action: 'freeze_deployments', reason: 'Error budget depleted or extreme burn rate' };
  }
  if (burnRate >= 3.0 || budgetRemainingPercent <= 20) {
    return { action: 'throttle_releases', reason: 'Accelerated burn rate or low budget' };
  }
  return { action: 'normal_operations', reason: 'Reliability within acceptable parameters' };
}

sre-web-exam-day-6:
function diffResourceState(desired: Record<string, any>, current: Record<string, any>): { create: string[]; update: string[]; delete: string[]; unchanged: string[] } {
  const create: string[] = [];
  const update: string[] = [];
  const unchanged: string[] = [];
  const del: string[] = [];
  for (const k of Object.keys(desired)) {
    if (!(k in current)) create.push(k);
    else if (JSON.stringify(desired[k]) !== JSON.stringify(current[k])) update.push(k);
    else unchanged.push(k);
  }
  for (const k of Object.keys(current)) {
    if (!(k in desired)) del.push(k);
  }
  return { create: create.sort(), update: update.sort(), delete: del.sort(), unchanged: unchanged.sort() };
}

sre-web-assign-day-6:
function topologicalResourceSort(dependencies: Record<string, string[]>): string[] {
  const visited = new Set<string>();
  const order: string[] = [];
  function visit(node: string) {
    if (visited.has(node)) return;
    visited.add(node);
    for (const dep of (dependencies[node] || [])) {
      visit(dep);
    }
    order.push(node);
  }
  for (const k of Object.keys(dependencies)) {
    visit(k);
  }
  return order;
}

sre-web-exam-day-7:
function detectConfigDrift(declared: Record<string, Record<string, any>>, live: Record<string, Record<string, any>>): { resourceId: string; property: string; expected: any; actual: any }[] {
  const drifts: { resourceId: string; property: string; expected: any; actual: any }[] = [];
  for (const [resId, spec] of Object.entries(declared)) {
    if (!(resId in live)) {
      drifts.push({ resourceId: resId, property: '__missing__', expected: true, actual: false });
      continue;
    }
    const liveSpec = live[resId] || {};
    for (const [prop, val] of Object.entries(spec)) {
      if (JSON.stringify(val) !== JSON.stringify(liveSpec[prop])) {
        drifts.push({ resourceId: resId, property: prop, expected: val, actual: liveSpec[prop] });
      }
    }
  }
  return drifts;
}

sre-web-assign-day-7:
function classifyDriftSeverity(drifts: { property: string }[], criticalProps: string[] = ['securityGroup', 'iamRole', 'sslCertificate']): 'none' | 'cosmetic' | 'critical' {
  if (drifts.length === 0) return 'none';
  const critical = new Set(criticalProps.map(p => p.toLowerCase()));
  for (const d of drifts) {
    if (critical.has(d.property.toLowerCase())) return 'critical';
  }
  return 'cosmetic';
}

sre-web-exam-day-8:
function evaluateRegionHealth(regions: { id: string; latencyMs: number; errorRate: number; isAlive: boolean }[]): { healthyRegions: string[]; failoverNeeded: boolean; primaryHealthy: boolean } {
  if (regions.length === 0) return { healthyRegions: [], failoverNeeded: false, primaryHealthy: false };
  const healthy = regions.filter(r => r.isAlive && r.latencyMs < 300 && r.errorRate < 0.05).map(r => r.id);
  const primaryId = regions[0].id;
  const primaryHealthy = healthy.includes(primaryId);
  const failoverNeeded = !primaryHealthy && healthy.length > 0;
  return { healthyRegions: healthy, failoverNeeded, primaryHealthy };
}

sre-web-assign-day-8:
function selectFailoverRegion(primaryId: string, regions: { id: string; healthScore: number; capacityPercent: number }[]): string | null {
  const candidates = regions.filter(r => r.id !== primaryId && r.healthScore >= 80 && r.capacityPercent <= 80);
  if (candidates.length === 0) return null;
  candidates.sort((a, b) => b.healthScore - a.healthScore || a.capacityPercent - b.capacityPercent);
  return candidates[0].id;
}

sre-web-exam-day-9:
function resolveWeightedDns(endpoints: { ip: string; weight: number }[], randomVal: number = 0.5): string {
  if (endpoints.length === 0) return '';
  const totalWeight = endpoints.reduce((sum, e) => sum + e.weight, 0);
  if (totalWeight <= 0) return endpoints[0].ip;
  const target = randomVal * totalWeight;
  let current = 0;
  for (const ep of endpoints) {
    current += ep.weight;
    if (target <= current) return ep.ip;
  }
  return endpoints[endpoints.length - 1].ip;
}

sre-web-assign-day-9:
function resolveGeographicDns(clientLat: number, clientLon: number, regions: { id: string; lat: number; lon: number }[]): string {
  if (regions.length === 0) return '';
  let bestId = regions[0].id;
  let minDistance = Infinity;
  for (const r of regions) {
    const d = Math.sqrt(Math.pow(clientLat - r.lat, 2) + Math.pow(clientLon - r.lon, 2));
    if (d < minDistance) {
      minDistance = d;
      bestId = r.id;
    }
  }
  return bestId;
}

sre-web-exam-day-10:
function simulateMultiRegionFailover(regions: Record<string, { healthy: boolean; latencyMs: number }>, primaryRegion: string): { activeRegion: string; failoverExecuted: boolean; rtoSeconds: number } {
  if (regions[primaryRegion]?.healthy) {
    return { activeRegion: primaryRegion, failoverExecuted: false, rtoSeconds: 0 };
  }
  let bestRegion: string | null = null;
  let minLatency = Infinity;
  for (const [id, stat] of Object.entries(regions)) {
    if (id !== primaryRegion && stat.healthy && stat.latencyMs < minLatency) {
      minLatency = stat.latencyMs;
      bestRegion = id;
    }
  }
  if (!bestRegion) {
    return { activeRegion: 'none', failoverExecuted: true, rtoSeconds: -1 };
  }
  return { activeRegion: bestRegion, failoverExecuted: true, rtoSeconds: 30 };
}

sre-web-assign-day-10:
function auditRtoCompliance(incidents: { id: string; targetRtoSeconds: number; actualRecoverySeconds: number }[]): { compliantCount: number; nonCompliantCount: number; complianceRatePercent: number } {
  if (incidents.length === 0) return { compliantCount: 0, nonCompliantCount: 0, complianceRatePercent: 100 };
  const compliantCount = incidents.filter(i => i.actualRecoverySeconds <= i.targetRtoSeconds).length;
  const nonCompliantCount = incidents.length - compliantCount;
  const complianceRatePercent = Math.round((compliantCount / incidents.length) * 100 * 100) / 100;
  return { compliantCount, nonCompliantCount, complianceRatePercent };
}

sre-web-exam-day-11:
function createRoundRobinBalancer(servers: string[]): { getNext(): string | null } {
  let index = 0;
  return {
    getNext(): string | null {
      if (servers.length === 0) return null;
      const s = servers[index % servers.length];
      index++;
      return s;
    }
  };
}

sre-web-assign-day-11:
function selectLeastConnections(servers: { id: string; activeConnections: number; healthy: boolean }[]): string | null {
  const healthy = servers.filter(s => s.healthy);
  if (healthy.length === 0) return null;
  let best = healthy[0];
  for (let i = 1; i < healthy.length; i++) {
    if (healthy[i].activeConnections < best.activeConnections) {
      best = healthy[i];
    }
  }
  return best.id;
}

sre-web-exam-day-12:
function evaluateProbes(status: { isProcessRunning: boolean; isDbConnected: boolean; isStartupComplete: boolean }): { canRouteTraffic: boolean; mustRestart: boolean; status: 'initializing' | 'healthy' | 'unhealthy' | 'dead' } {
  if (!status.isProcessRunning) {
    return { canRouteTraffic: false, mustRestart: true, status: 'dead' };
  }
  if (!status.isStartupComplete) {
    return { canRouteTraffic: false, mustRestart: false, status: 'initializing' };
  }
  if (!status.isDbConnected) {
    return { canRouteTraffic: false, mustRestart: false, status: 'unhealthy' };
  }
  return { canRouteTraffic: true, mustRestart: false, status: 'healthy' };
}

sre-web-assign-day-12:
function aggregateHealthChecks(checks: { name: string; status: 'pass' | 'fail' | 'warn'; latencyMs: number }[]): { overall: 'healthy' | 'degraded' | 'unhealthy'; failingChecks: string[] } {
  const failingChecks = checks.filter(c => c.status === 'fail').map(c => c.name);
  if (failingChecks.length > 0) {
    return { overall: 'unhealthy', failingChecks };
  }
  const hasWarn = checks.some(c => c.status === 'warn');
  return { overall: hasWarn ? 'degraded' : 'healthy', failingChecks: [] };
}

sre-web-exam-day-13:
function computeBackoffDelay(attempt: number, baseDelayMs: number = 100, maxDelayMs: number = 5000, factor: number = 2): number {
  const delay = baseDelayMs * Math.pow(factor, attempt);
  return Math.min(maxDelayMs, Math.round(delay));
}

sre-web-assign-day-13:
function applyFullJitter(calculatedDelayMs: number, randomFactor: number = 0.5): number {
  return Math.floor(randomFactor * (calculatedDelayMs + 1));
}

sre-web-exam-day-14:
function createCircuitBreaker(failureThreshold: number = 3, resetTimeoutMs: number = 1000) {
  let state: 'CLOSED' | 'OPEN' | 'HALF_OPEN' = 'CLOSED';
  let failureCount = 0;
  let lastFailureTime = 0;
  function evaluateState(nowMs: number): 'CLOSED' | 'OPEN' | 'HALF_OPEN' {
    if (state === 'OPEN' && nowMs - lastFailureTime >= resetTimeoutMs) {
      state = 'HALF_OPEN';
    }
    return state;
  }
  return {
    recordSuccess(): void {
      state = 'CLOSED';
      failureCount = 0;
    },
    recordFailure(nowMs: number): void {
      lastFailureTime = nowMs;
      failureCount++;
      if (state === 'HALF_OPEN' || failureCount >= failureThreshold) {
        state = 'OPEN';
      }
    },
    getState(nowMs: number): 'CLOSED' | 'OPEN' | 'HALF_OPEN' {
      return evaluateState(nowMs);
    },
    canExecute(nowMs: number): boolean {
      const current = evaluateState(nowMs);
      return current !== 'OPEN';
    }
  };
}

sre-web-assign-day-14:
function formatCircuitBreakerStatus(state: 'CLOSED' | 'OPEN' | 'HALF_OPEN', failures: number, threshold: number): { status: string; isDegraded: boolean; message: string } {
  const isDegraded = state !== 'CLOSED';
  let message = '';
  if (state === 'CLOSED') message = 'Normal operation: ' + failures + '/' + threshold + ' failures';
  else if (state === 'OPEN') message = 'Circuit Tripped: rejecting downstream requests';
  else message = 'Probing downstream recovery with trial requests';
  return { status: state, isDegraded, message };
}

sre-web-exam-day-15:
function createBulkheadPool(maxConcurrent: number, maxQueue: number) {
  let active = 0;
  let queue = 0;
  return {
    tryAcquire(): boolean {
      if (active < maxConcurrent) {
        active++;
        return true;
      }
      if (queue < maxQueue) {
        queue++;
        return true;
      }
      return false;
    },
    release(): void {
      if (queue > 0) {
        queue--;
      } else if (active > 0) {
        active--;
      }
    },
    getActiveCount(): number { return active; },
    getQueueCount(): number { return queue; }
  };
}

sre-web-assign-day-15:
function calculateTimeoutBudget(clientTimeoutMs: number, hops: { service: string; maxLatencyMs: number }[]): { remainingBudgetMs: number; feasible: boolean; bottleneck: string | null } {
  if (hops.length === 0) return { remainingBudgetMs: clientTimeoutMs, feasible: true, bottleneck: null };
  const totalHopMs = hops.reduce((sum, h) => sum + h.maxLatencyMs, 0);
  const remainingBudgetMs = clientTimeoutMs - totalHopMs;
  const feasible = remainingBudgetMs >= 0;
  let bottleneck: string | null = hops[0].service;
  let maxLatency = hops[0].maxLatencyMs;
  for (let i = 1; i < hops.length; i++) {
    if (hops[i].maxLatencyMs > maxLatency) {
      maxLatency = hops[i].maxLatencyMs;
      bottleneck = hops[i].service;
    }
  }
  return { remainingBudgetMs, feasible, bottleneck };
}
